                    skill_name[:50],
                    description,
                    f"skills/{skill_md}",
                    f"skill_{skill_name.replace('-', '_').replace(' ', '_')}"
                )
                skill_ids[skill_name] = skill_node_id
                self.add_edge(category_id, skill_node_id, "belongs_to")
